import pandas as pd

def clean(df):
    df = df.copy()
    # strip whitespace from text columns
    for col in ["Category", "Region", "Date", "Product"]:
        if col in df.columns:
            df[col] = df[col].astype(str).str.strip()
    # standardise Category label variants
    cat_map = {
        "Accesories": "Accessories",
        "electronics": "Electronics",
        "Electornics": "Electronics",
        "office supplies": "Office Supplies",
        "Office Suplies": "Office Supplies"
    }
    df["Category"] = df["Category"].replace(cat_map)
    # ensure numeric types
    for col in ["Order_ID", "Quantity", "Price", "Revenue"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")
    # enforce Revenue = Quantity * Price
    df["Revenue"] = df["Quantity"] * df["Price"]
    # optional date normalisation
    # try to parse dates, keep as string for downstream use
    return df

def answer(df):
    dfc = clean(df)
    # total revenue by category after cleaning
    grouped = dfc.groupby("Category", dropna=False)["Revenue"].sum()
    allowed = {"Electronics", "Accessories", "Furniture", "Office Supplies"}
    result = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        if k in allowed:
            result[k] = float(v)
    return result
